function price(total, discount) { return discount(total); }
const halfPrice = value => value / 2;
console.log(price(10, halfPrice));

const listeners = [];
listeners.push(value => console.log("Score " + value));
for (const notify of listeners) notify(8);

const oldWeather = { fahrenheit: 68 };
function asCelsius(weather) { return (weather.fahrenheit - 32) * 5 / 9; }
console.log(asCelsius(oldWeather));

const greet = name => "Hi " + name;
const excited = fn => name => fn(name) + "!";
console.log(excited(greet)("Asha"));

const readTitle = () => "Moon";
const readPages = () => 24;
function bookSummary() { return readTitle() + ": " + readPages() + " pages"; }
console.log(bookSummary());

let score = 0;
const addPoint = { execute() { score++; } };
const queue = [addPoint, addPoint];
queue.forEach(command => command.execute());
console.log(score);

let state = "closed";
function openDoor() { if (state === "closed") state = "open"; }
openDoor();
console.log(state);

const choices = { title: "Moon", color: "blue" };
function buildCard(options) { return options.title + " / " + (options.color ?? "white"); }
console.log(buildCard(choices));

const settings = { sound: true };
const first = settings;
const second = settings;
first.sound = false;
console.log(second.sound);
